def dict_diff(a, b):
    added = []
    removed = []
    changed = {}
    for k in b:
        if k not in a:
            added.append(k)
    for k in a:
        if k not in b:
            removed.append(k)
        elif a[k] != b[k]:
            changed[k] = (a[k], b[k])
    added.sort()
    removed.sort()
    return {'added': added, 'removed': removed, 'changed': changed}

def zeckendorf_length(n):
    if n == 0:
        return 0
    fib = [1, 2]
    while fib[-1] + fib[-2] <= n:
        fib.append(fib[-1] + fib[-2])
    count = 0
    remaining = n
    for f in reversed(fib):
        if f <= remaining:
            remaining -= f
            count += 1
    return count

def is_valid_date_range(start, end):
    def valid_date(s):
        pieces = s.split('-')
        if len(pieces) != 3:
            return None
        y_str, m_str, d_str = pieces
        if not (y_str.isdigit() and m_str.isdigit() and d_str.isdigit()):
            return None
        if len(y_str) != 4 or len(m_str) != 2 or len(d_str) != 2:
            return None
        y, m, d = int(y_str), int(m_str), int(d_str)
        if m < 1 or m > 12:
            return None
        leap = (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
        days_in_month = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if d < 1 or d > days_in_month[m - 1]:
            return None
        return (y, m, d)
    a = valid_date(start)
    b = valid_date(end)
    if a is None or b is None:
        return False
    return a <= b

def sign_changes_count(lst):
    def sign_of(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
