def flatten_and_count(nested):
    def flatten(items):
        for item in items:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item
    counts = {}
    for value in flatten(nested):
        counts[value] = counts.get(value, 0) + 1
    return counts

