        return lst[len(lst) - n:]
    if len(lst) == n:
        return lst
    return [pad] * (n - len(lst)) + lst

def char_count_difference(a, b):
    from collections import Counter
    ca = Counter(a)
    cb = Counter(b)
    chars = set(ca) | set(cb)
    return sum(abs(ca[c] - cb[c]) for c in chars)

def rle_longest_run_value(lst):
    if not lst:
        return None
    best_value = lst[0]
    best_length = 1
    current_value = lst[0]
    current_length = 1
    for item in lst[1:]:
        if item == current_value:
            current_length += 1
        else:
            current_value = item
            current_length = 1
        if current_length > best_length:
            best_length = current_length
            best_value = current_value
    return best_value

