def midpoint_date(date1, date2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def days_in_month(y, m):
        lens = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lens[m - 1]
    def to_ordinal(y, m, d):
        total = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
        for month in range(1, m):
            total += days_in_month(y, month)
        return total + d
    def from_ordinal(n):
        y = n // 365 + 1
        while to_ordinal(y, 1, 1) > n:
            y -= 1
        while to_ordinal(y + 1, 1, 1) <= n:
            y += 1
        remaining = n - to_ordinal(y, 1, 1) + 1
        m = 1
        while remaining > days_in_month(y, m):
            remaining -= days_in_month(y, m)
            m += 1
        return (y, m, remaining)
    o1 = to_ordinal(*date1)
    o2 = to_ordinal(*date2)
    mid = o1 + (o2 - o1) // 2
    return from_ordinal(mid)

def days_between(date1, date2):
    def is_leap_year(year):
        return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0

    def days_before_year(year):
        y = year - 1
        return y * 365 + y // 4 - y // 100 + y // 400

    def days_before_month(year, month):
        month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if is_leap_year(year):
            month_days[1] = 29
        return sum(month_days[:month - 1])

    def to_ordinal(date):
        y, m, d = date
        return days_before_year(y) + days_before_month(y, m) + d

    return to_ordinal(date2) - to_ordinal(date1)

