def total_minutes_worked(sessions):
    def to_minutes(t):
        parts = t.split(':')
        return int(parts[0]) * 60 + int(parts[1])
    total = 0
    for clock_in, clock_out in sessions:
        total += to_minutes(clock_out) - to_minutes(clock_in)
    return total
